import re

# ============================================================================
# MODEL OF THE BOX (level 1)
#
# Beliefs (with evidence):
#
# * The board is 64x64. There is a "right edge" column pair c62-63 that fills
#   with colour 0 from the top downward, 2 rows per action, as a step counter.
#   Every action (ACTION1-4, CLICK) advances this counter by one step = 2 rows
#   [E1,E2,E3,E4,E5,...]. When the counter reaches the bottom (row 63) the
#   next action triggers GAME_OVER [E15,E35,E62]. RESET restores everything
#   to the level's initial state [E16,E36].
#
# * There are "sliding tile" gadgets. The 4x4 block at rows 19-22, cols 23-42
#   holds a sliding-window of coloured 2x2 tiles (9/a/2). ACTION3 slides the
#   window left by 4 columns (wrapping within the 20-wide strip) [E12,E13,
#   E27,E28,E30,E38,E44]. ACTION1 slides it right by 2 [E12,E13,E24,E28,E50].
#   ACTION2 / ACTION4 rotate the tiles in place (swap the 9/a ordering)
#   [E2,E4,E7,E11,E19,E25,E40,E42,E48,E54].
#   The exact tile colours depend on the (hidden) tile sequence and the
#   current window offset; we model the offset as a state variable.
#
# * There are 3x3 "button" gadgets at (rows 49-51, cols 24-36) and
#   (rows 54-56, cols 24-36) and (rows 59-61, cols 24-36). Clicking one of
#   the small button objects (x,y) toggles that button's colour between e
#   (lit) and 0 (unlit) [E1,E3,E4,E5,E6,E7,E8,E9,E18,E19,E20,E21,E22,E23,
#   E25,E26,E29,E35,E41,E43,E45,E51,E53,E55,E59]. The rightmost button in
#   each row (col 34-36) is toggled by CLICK 35 50 / 35 55 / 35 60, the
#   middle by 30 50 / 30 55 / 30 60, the left by 25 50 / 25 55 / 25 60.
#   Clicking elsewhere does nothing [E17,E31,E33,E47,E49,E57,E61].
#
# * The goal (?) is to make all three buttons in the three gadget rows lit
#   (colour e) simultaneously. The level-complete check likely fires when
#   the button pattern matches a target; we guess "all lit". Marked "?".
#
# * GAME_OVER: when the right-edge counter reaches the bottom row (row 63)
#   the next action yields GAME_OVER [E15,E35,E62]. RESET from GAME_OVER
#   restores the level [E16,E36].
#
# * The current screen is given as "frame"; we replay from it. History is
#   used only to recover the sliding-window offset and button states that
#   the frame already shows. We recompute from the frame where possible.
# ============================================================================

BUTTON_ROWS = [49, 54, 59]          # top row of each 3x3 button gadget
BUTTON_COLS = [24, 29, 34]          # left col of each button (3 wide)
BUTTON_CENTERS = [(25,50),(30,50),(35,50),
                  (25,55),(30,55),(35,55),
                  (25,60),(30,60),(35,60)]

SLIDE_TOP, SLIDE_BOT = 19, 22
SLIDE_LEFT, SLIDE_RIGHT = 23, 42
SLIDE_WIDTH = SLIDE_RIGHT - SLIDE_LEFT + 1   # 20

def parse_frame(frame):
    return [list(row) for row in frame]

def frame_to_rows(grid):
    return [''.join(r) for r in grid]

def find_button_at(x, y):
    """Return (row_index, col_index) of button gadget clicked, or None."""
    for ri, br in enumerate(BUTTON_ROWS):
        for ci, bc in enumerate(BUTTON_COLS):
            if bc <= x <= bc + 2 and br <= y <= br + 2:
                return (ri, ci)
    return None

def toggle_button(grid, ri, ci):
    br = BUTTON_ROWS[ri]
    bc = BUTTON_COLS[ci]
    # colour of the 3x3: e (lit) <-> 0 (unlit)
    cur = grid[br][bc]
    new = '0' if cur == 'e' else 'e'
    for r in range(br, br + 3):
        for c in range(bc, bc + 3):
            grid[r][c] = new

def slide_window(grid, direction):
    """Slide the 4x4 tile window at rows 19-22 cols 23-42.
    direction = +1 (right, ACTION1) or -1 (left, ACTION3).
    The strip is 20 wide; window is 4 wide; slide by 2 (right) or 4 (left).
    We model the strip as a circular buffer of 2x2 tiles. Since we don't
    know the full tile sequence, we approximate: shift the visible 4x4 block
    by the step, filling new columns with a repeating pattern derived from
    the current visible tiles (best guess, marked ?)."""
    # Extract current 4x4 block (2x2 tiles -> 4x4 cells)
    rows = range(SLIDE_TOP, SLIDE_TOP + 4)
    # We'll shift the 4x4 block horizontally within the 20-wide strip.
    # Step: ACTION1 moves right by 2, ACTION3 moves left by 4 (mod 20).
    step = 2 if direction > 0 else -4
    # Extract the 4x4 tile grid (each tile 2x2)
    tiles = []
    for tr in range(2):
        trow = []
        for tc in range(2):
            r0 = SLIDE_TOP + tr * 2
            c0 = SLIDE_LEFT + tc * 2
            trow.append(grid[r0][c0])
        tiles.append(trow)
    # We don't know the hidden tiles; approximate by rotating the 2x2 tile
    # matrix (best guess ?). This matches E12/E13 where the pattern shifts.
    if direction > 0:
        # rotate tiles right
        tiles = [[tiles[1][0], tiles[0][0]],
                 [tiles[1][1], tiles[0][1]]]
    else:
        tiles = [[tiles[0][1], tiles[1][1]],
                 [tiles[0][0], tiles[1][0]]]
    # Write back
    for tr in range(2):
        for tc in range(2):
            r0 = SLIDE_TOP + tr * 2
            c0 = SLIDE_LEFT + tc * 2
            col = tiles[tr][tc]
            for dr in range(2):
                for dc in range(2):
                    grid[r0 + dr][c0 + dc] = col

def rotate_tiles(grid):
    """ACTION2/ACTION4: swap the 9/a ordering in the 4x4 block (best guess ?)."""
    for r in range(SLIDE_TOP, SLIDE_TOP + 4):
        for c in range(SLIDE_LEFT, SLIDE_RIGHT + 1):
            v = grid[r][c]
            if v == '9':
                grid[r][c] = 'a'
            elif v == 'a':
                grid[r][c] = '9'

def advance_counter(grid):
    """Fill next 2 rows of right-edge counter (c62-63) with 0.
    Returns True if counter was already full (game over)."""
    for r in range(0, 64, 2):
        if grid[r][62] != '0':
            grid[r][62] = '0'
            grid[r][63] = '0'
            grid[r + 1][62] = '0'
            grid[r + 1][63] = '0'
            return False
    return True  # already full -> next action = GAME_OVER

def counter_full(grid):
    return grid[62][62] == '0' and grid[63][62] == '0'

def diff_grids(old, new):
    changes = {}
    for r in range(64):
        for c in range(64):
            if old[r][c] != new[r][c]:
                changes[f"{r},{c}"] = new[r][c]
    return changes

def all_buttons_lit(grid):
    for br in BUTTON_ROWS:
        for bc in BUTTON_COLS:
            if grid[br][bc] != 'e':
                return False
    return True

def predict(probe):
    level = probe.get("level", 0)
    frame = probe.get("frame")
    actions = probe.get("actions", [])
    history = probe.get("history", [])

    if frame is None:
        return {"steps": []}

    grid = parse_frame(frame)
    steps = []
    game_over = False

    for action in actions:
        old = [row[:] for row in grid]
        state = "NOT_FINISHED"
        levels = 0

        if game_over:
            # Only RESET works
            if action == "RESET":
                game_over = False
                # Reset: restore initial state. We can't know it exactly;
                # approximate by clearing counter and re-lighting buttons (?).
                for r in range(64):
                    grid[r][62] = 'e'
                    grid[r][63] = 'e'
                # best guess: buttons reset to lit (initial state had e)
                for br in BUTTON_ROWS:
                    for bc in BUTTON_COLS:
                        for dr in range(3):
                            for dc in range(3):
                                grid[br+dr][bc+dc] = 'e'
            else:
                # nothing changes
                pass
        else:
            if action == "RESET":
                # reset level
                for r in range(64):
                    grid[r][62] = 'e'
                    grid[r][63] = 'e'
                for br in BUTTON_ROWS:
                    for bc in BUTTON_COLS:
                        for dr in range(3):
                            for dc in range(3):
                                grid[br+dr][bc+dc] = 'e'
            elif action.startswith("CLICK"):
                m = re.match(r"CLICK\s+(\d+)\s+(\d+)", action)
                if m:
                    x, y = int(m.group(1)), int(m.group(2))
                    btn = find_button_at(x, y)
                    if btn is not None:
                        toggle_button(grid, btn[0], btn[1])
                    # advance counter
                    if counter_full(grid):
                        game_over = True
                    else:
                        advance_counter(grid)
            elif action == "ACTION1":
                slide_window(grid, +1)
                if counter_full(grid):
                    game_over = True
                else:
                    advance_counter(grid)
            elif action == "ACTION3":
                slide_window(grid, -1)
                if counter_full(grid):
                    game_over = True
                else:
                    advance_counter(grid)
            elif action in ("ACTION2", "ACTION4"):
                rotate_tiles(grid)
                if counter_full(grid):
                    game_over = True
                else:
                    advance_counter(grid)

            # check goal (?) : all buttons lit
            if not game_over and all_buttons_lit(grid):
                levels = 1
                state = "WIN"

        if game_over and state != "WIN":
            state = "GAME_OVER"

        changes = diff_grids(old, grid)
        steps.append({"changes": changes, "levels": levels, "state": state})

    return {"steps": steps}
